/* Phoenix time (UTC-7 all year) */
function phx(ms){ var d=new Date(ms-7*3600000); return {y:d.getUTCFullYear(),m:d.getUTCMonth(),d:d.getUTCDate(),wd:d.getUTCDay(),h:d.getUTCHours(),mi:d.getUTCMinutes()}; }
function isOpen(ms){ var p=phx(ms), m=p.h*60+p.mi; if(p.wd>=1&&p.wd<=5) return m>=300&&m<990; if(p.wd===6) return m>=360&&m<720; return false; }
function nextOpen(ms){ for(var i=0;i<8*96;i++){ var t=ms+i*15*60000; if(isOpen(t)) return t; } return ms; }
function closesAt(ms){ return phx(ms).wd===6?'12:00 PM':'4:30 PM'; }
function dayName(wd,l){ return (l==='es'?['domingo','lunes','martes','mi\u00e9rcoles','jueves','viernes','s\u00e1bado']:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'])[wd]; }
function statusLine(l){ var now=Date.now(); if(isOpen(now)) return l==='es'?'Abierto ahora \u00b7 cierra a las '+closesAt(now):'Open now \u00b7 closes '+closesAt(now);
  var o=phx(nextOpen(now)), t=(o.wd===6?'6:00 AM':'5:00 AM'), today=phx(now), tom=phx(now+86400000);
  var when=(o.d===today.d)?(l==='es'?'hoy':'today'):(o.d===tom.d)?(l==='es'?'ma\u00f1ana':'tomorrow'):dayName(o.wd,l);
  return l==='es'?'Cerrado ahora \u00b7 abre '+when+' a las '+t:'Closed now \u00b7 opens '+when+' at '+t; }
function isoPhx(ms){ var p=phx(ms); return p.y+'-'+String(p.m+1).padStart(2,'0')+'-'+String(p.d).padStart(2,'0'); }
function addDays(s,n){ var t=new Date(s+'T12:00:00Z'); t.setUTCDate(t.getUTCDate()+n); return t.toISOString().slice(0,10); }
function wday(s){ return new Date(s+'T12:00:00Z').getUTCDay(); }
function nextDeliveryDays(n){ var out=[], s=addDays(isoPhx(Date.now()),1); while(out.length<n){ if(wday(s)!==0) out.push(s); s=addDays(s,1); } return out; }
function fmtDay(s,l){ return new Intl.DateTimeFormat(l==='es'?'es-MX':'en-US',{timeZone:'UTC',weekday:'short',month:'short',day:'numeric'}).format(new Date(s+'T12:00:00Z')); }
function winsFor(s){ var w=wday(s); return w===0?[]:w===6?['w1','w2']:['w1','w2','w3']; }
